INSERT INTO dos.foundation_sod_rules VALUES ('payment_initiator_vs_approver', NULL, 'Payment initiator must not be payment approver', 'منشئ الدفعة يجب ألا يوافق عليها', 'A user holding a payment-initiator role cannot also hold a payment-approver role on the same tenant.', 'لا يجوز للمستخدم الذي يحمل دور منشئ الدفع أن يحمل أيضًا دور الموافقة على الدفع.', 'mutually_exclusive_roles', '{"role_pair": ["payment_initiator", "payment_approver"]}', 'critical', true, 'Reassign one of the two roles to another user; if business-required, file a documented compensating control.', 'أعد تعيين أحد الدورين إلى مستخدم آخر؛ إذا اقتضى العمل ذلك، سجل ضابطًا تعويضيًا موثقًا.', true, '2026-04-30 03:44:19.10567+00', NULL);
INSERT INTO dos.foundation_sod_rules VALUES ('vendor_setup_vs_payment', NULL, 'Vendor setup must not also approve payments', 'إنشاء المورد يجب ألا يوافق على الدفعات', 'Creating a vendor and approving payments to that vendor must be done by different users.', 'يجب أن يقوم بإنشاء المورد والموافقة على الدفعات له مستخدمان مختلفان.', 'blocked_role_pair', '{"role_pair": ["vendor_admin", "payment_approver"]}', 'high', true, 'Split vendor administration from payment approval; route through the foundation roles page.', 'افصل إدارة الموردين عن الموافقة على المدفوعات؛ وجِّه ذلك عبر صفحة أدوار المؤسسة.', true, '2026-04-30 03:44:19.10567+00', NULL);
INSERT INTO dos.foundation_sod_rules VALUES ('user_admin_vs_audit', NULL, 'User administrators cannot also be auditors', 'مدير المستخدمين لا يكون مدققًا', 'A user who can grant access cannot also audit access — separation required for ISO 27001 + SAMA.', 'لا يجوز للمستخدم الذي يمنح الصلاحيات أن يدققها أيضًا.', 'blocked_role_pair', '{"role_pair": ["foundation_admin", "auditor"]}', 'critical', true, 'Move audit role to an independent user; consider a compensating "read-only auditor" view.', 'انقل دور التدقيق إلى مستخدم مستقل؛ فكِّر في منح "مدقق للقراءة فقط".', true, '2026-04-30 03:44:19.10567+00', NULL);
INSERT INTO dos.foundation_sod_rules VALUES ('approver_self_approval', NULL, 'Approvers cannot self-approve their own requests', 'مقدم الطلب لا يوافق على طلبه', 'The approver of a workflow step cannot be the same user who initiated the request.', 'لا يجوز للموافق في خطوة الإجراء أن يكون هو من بدأ الطلب.', 'approval_self_block', '{"applies_to": ["approve_payment", "approve_contract", "approve_policy", "approve_promotion", "approve_termination", "approve_hire"]}', 'critical', true, 'Route approval to the next-level approver per the authority matrix.', 'حوِّل الموافقة إلى المستوى الأعلى وفق مصفوفة الصلاحيات.', true, '2026-04-30 03:44:19.10567+00', NULL);
INSERT INTO dos.foundation_sod_rules VALUES ('committee_self_block', NULL, 'Committee members cannot vote on items they sponsored', 'أعضاء اللجنة لا يصوتون على البنود التي اقترحوها', 'A committee member who proposed an agenda item cannot also vote on it.', 'عضو اللجنة الذي اقترح بندًا في جدول الأعمال لا يجوز له التصويت عليه.', 'committee_self_block', '{"applies_to": ["all"]}', 'high', true, 'Recuse the proposing member; record the recusal in meeting minutes.', 'استبعد العضو المقترح؛ ووثِّق ذلك في محضر الاجتماع.', true, '2026-04-30 03:44:19.10567+00', NULL);
INSERT INTO dos.foundation_sod_rules VALUES ('approver_quiet_period', NULL, 'Approvers must wait 24h after their delegation grant', 'يجب على الموافق الانتظار 24 ساعة بعد منح التفويض', 'A user freshly granted approval authority should wait 24 hours before exercising it (anti-collusion).', 'يجب على المستخدم الذي حصل على صلاحية الموافقة الانتظار 24 ساعة قبل استخدامها (لمنع التواطؤ).', 'time_separation', '{"min_hours": 24, "applies_to": ["approve_payment", "approve_contract"]}', 'medium', false, 'Defer the approval; if urgent, escalate to the next authority level.', 'أجِّل الموافقة؛ وإذا كانت عاجلة، صعِّدها إلى المستوى التالي.', true, '2026-04-30 03:44:19.10567+00', NULL);


