-- SECTION 6 — FRAMEWORK → COUNTRY MAPPING (derived)
-- Root DOS-AIO-Specs/*.csv files have no country_code column.
-- Mapping is derived from framework_code prefix.
-- ============================================================
CREATE TABLE IF NOT EXISTS public.framework_country_map (
    framework_code TEXT PRIMARY KEY,
    country_code   TEXT NOT NULL,            -- ISO alpha-3
    scope          TEXT NOT NULL,            -- 'national' | 'international'
    regulator_code TEXT,
    controls_count INT
);

