-- ============================================================
-- SECTION 14 — PERSONA-DRIVEN TENANT PROVISIONING (engine SQL)
-- ============================================================
-- A persona is the named (sector + size + org_type + business_model + ownership)
-- combination that resolves to a unique applicability set. matrix5 holds 41 personas;
-- this section provides the SQL functions that fan a persona_id out into per-module
-- INSERT statements.
-- ============================================================

-- ── Helper: resolve persona_id from raw tenant dimensions ──────────
CREATE OR REPLACE FUNCTION fn_resolve_persona(
    p_sector         TEXT,
    p_size           TEXT,
    p_org_type       TEXT,
    p_business_model TEXT,
    p_ownership      TEXT
) RETURNS INT LANGUAGE sql STABLE AS $$
    SELECT persona_id
    FROM public.matrix5_composite_personas
    WHERE sector         = p_sector
      AND size           = p_size
      AND org_type       = p_org_type
      AND business_model = p_business_model
      AND ownership      = p_ownership
    LIMIT 1;
$$;

-- ── Main: fan out a persona into per-tenant per-module rows ────────
CREATE OR REPLACE FUNCTION fn_provision_tenant(
    p_tenant_id  TEXT,
    p_persona_id INT
) RETURNS TABLE (
    module_code     TEXT,
    framework_code  TEXT,
    applicability   TEXT,
    controls_seeded INT,
    evidence_seeded INT,
    risks_seeded    INT
) LANGUAGE plpgsql AS $$
DECLARE
    v_mandatory   TEXT[];
    v_conditional TEXT[];
    v_voluntary   TEXT[];
BEGIN
    -- 1. Pull the persona's framework lists (semicolon-delimited in matrix5)
    SELECT regexp_split_to_array(mandatory_frameworks,   ';\s*'),
           regexp_split_to_array(conditional_frameworks, ';\s*'),
           regexp_split_to_array(voluntary_frameworks,   ';\s*')
      INTO v_mandatory, v_conditional, v_voluntary
    FROM public.matrix5_composite_personas
    WHERE persona_id = p_persona_id;

    -- 2. For each framework, route to the owning module and seed its slice
    RETURN QUERY
    WITH fw AS (
        SELECT unnest(v_mandatory)   AS framework_code, 'mandatory'::TEXT   AS applicability
        UNION ALL
        SELECT unnest(v_conditional), 'conditional'
        UNION ALL
        SELECT unnest(v_voluntary),   'voluntary'
    ),
    -- Module routing rules (framework_code → module)
    routing AS (
        SELECT framework_code, applicability,
               CASE
                 WHEN framework_code IN ('NCA-ECC','NCNICC','NCA-CSCC','NCA-OTCC','NCA-CCC','NCA-DCC','NCA-NCS')
                                                            THEN 'compliance-cyber'
                 WHEN framework_code LIKE 'SAMA-%' AND framework_code <> 'SAMA-PSR' THEN 'compliance-financial'
                 WHEN framework_code IN ('SAMA-PSR','PCI-DSS','SWIFT-CSP')          THEN 'payments'
                 WHEN framework_code = 'PDPL'                                       THEN 'privacy'
                 WHEN framework_code LIKE 'CMA-%'                                   THEN 'governance'
                 WHEN framework_code LIKE 'ZATCA-%'                                 THEN 'finance-tax'
                 WHEN framework_code LIKE 'MHRSD-%'                                 THEN 'team-hr'
                 WHEN framework_code = 'MOCI-COMPANIES'                             THEN 'foundation'
                 WHEN framework_code IN ('MOCI-CONSUMER','MOCI-ECOM')               THEN 'customer'
                 WHEN framework_code = 'ISO22301'                                   THEN 'bcp'
                 WHEN framework_code IN ('ISO27001','NIST-CSF','SOC2')              THEN 'isms'
                 WHEN framework_code LIKE 'MOH-%' OR framework_code = 'CBAHI'       THEN 'healthcare'
                 WHEN framework_code LIKE 'SFDA-%'                                  THEN 'pharma'
                 WHEN framework_code LIKE 'CST-%'                                   THEN 'telecom-ict'
                 WHEN framework_code LIKE 'DGA-%' OR framework_code LIKE 'NDMO-%'   THEN 'gov-data'
                 ELSE 'compliance-other'
               END AS module_code
        FROM fw
    )
    SELECT r.module_code, r.framework_code, r.applicability,
           (SELECT COUNT(*)::INT FROM public.controls          WHERE framework_code = r.framework_code) AS controls_seeded,
           (SELECT COUNT(*)::INT FROM public.evidence_mapping  WHERE framework_code = r.framework_code) AS evidence_seeded,
           (SELECT COUNT(*)::INT FROM public.risk_assessment   WHERE framework_code = r.framework_code) AS risks_seeded
    FROM routing r
    ORDER BY r.module_code, r.applicability, r.framework_code;
END;
$$;

-- ── Atomic per-tenant fan-out (writes the actual rows) ─────────────
CREATE OR REPLACE PROCEDURE sp_seed_tenant(
    p_tenant_id  TEXT,
    p_persona_id INT
) LANGUAGE plpgsql AS $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT * FROM fn_provision_tenant(p_tenant_id, p_persona_id) LOOP
        -- 1. Subscribe framework
        INSERT INTO tenant.frameworks_subscribed (tenant_id, framework_code, applicability, persona_id, subscribed_at)
        VALUES (p_tenant_id, r.framework_code, r.applicability, p_persona_id, NOW())
        ON CONFLICT DO NOTHING;

        -- 2. Seed controls (filtered by framework_code)
        INSERT INTO tenant.controls (tenant_id, control_id, framework_code, control_number, title_en, title_ar,
                                     requirement_en, requirement_ar, control_type, priority, maturity_level,
                                     module_code, status)
        SELECT p_tenant_id, c.control_id, c.framework_code, c.control_number, c.title_en, c.title_ar,
               c.requirement_en, c.requirement_ar, c.control_type, c.priority, c.maturity_level,
               r.module_code, 'planned'
        FROM public.controls c
        WHERE c.framework_code = r.framework_code
        ON CONFLICT DO NOTHING;

        -- 3. Seed evidence requirements
        INSERT INTO tenant.evidence_required (tenant_id, mapping_id, control_id, framework_code, evidence_type_code,
                                              is_mandatory, retention_months, review_frequency_months, approval_role,
                                              module_code, status)
        SELECT p_tenant_id, em.mapping_id, em.control_id, em.framework_code, em.evidence_type_code,
               em.is_mandatory, em.min_retention_months, em.review_frequency_months, em.approval_role,
               r.module_code, 'requested'
        FROM public.evidence_mapping em
        WHERE em.framework_code = r.framework_code
        ON CONFLICT DO NOTHING;

        -- 4. Seed evidence lifecycle states (DEFINE→APPROVE→IMPLEMENT→MAINTAIN→REVIEW)
        INSERT INTO tenant.evidence_lifecycle_state (tenant_id, lifecycle_id, mapping_id, control_id, framework_code,
                                                     stage_code, stage_order, duration_days, responsible_role,
                                                     module_code, is_active_stage)
        SELECT p_tenant_id, el.lifecycle_id, el.mapping_id, el.control_id, el.framework_code,
               el.stage_code, el.stage_order, el.duration_days, el.responsible_role,
               r.module_code, el.is_active_stage
        FROM public.evidence_lifecycle el
        WHERE el.framework_code = r.framework_code
        ON CONFLICT DO NOTHING;

        -- 5. Seed risk register
        INSERT INTO tenant.risk_register (tenant_id, risk_id, control_id, framework_code, primary_risk_category,
                                          inherent_risk_score, inherent_risk_level, control_effectiveness,
                                          residual_risk_score, residual_risk_level, risk_treatment, risk_owner_role,
                                          module_code)
        SELECT p_tenant_id, ra.risk_id, ra.control_id, ra.framework_code, ra.primary_risk_category,
               ra.inherent_risk_score, ra.inherent_risk_level, ra.control_effectiveness,
               ra.residual_risk_score, ra.residual_risk_level, ra.risk_treatment, ra.risk_owner_role,
               r.module_code
        FROM public.risk_assessment ra
        WHERE ra.framework_code = r.framework_code
        ON CONFLICT DO NOTHING;
    END LOOP;

    -- 6. Materialize the persona evidence pack (matrix6) into a tenant-facing audit shortlist
    INSERT INTO tenant.persona_evidence_pack (tenant_id, persona_id, sector, size, org_type,
                                              framework_code, key_evidence)
    SELECT p_tenant_id, m6.persona_id, m6.sector, m6.size, m6.org_type, m6.framework, m6.key_evidence
    FROM public.matrix6_evidence_per_persona m6
    WHERE m6.persona_id = p_persona_id
    ON CONFLICT DO NOTHING;

    -- 7. Apply ownership-driven audit cadence (matrix4)
    INSERT INTO tenant.audit_schedule (tenant_id, framework_code, scrutiny_level, audit_frequency)
    SELECT p_tenant_id, m4.additional_framework, m4.scrutiny_level, m4.audit_frequency
    FROM public.matrix4_ownership_obligations m4
    WHERE m4.ownership = (SELECT ownership FROM public.matrix5_composite_personas WHERE persona_id = p_persona_id)
    ON CONFLICT DO NOTHING;
END;
$$;

-- ── Usage examples ─────────────────────────────────────────────────
-- Resolve a tenant's persona from its raw profile:
--   SELECT fn_resolve_persona('BANKING','ENTERPRISE','JSC_LISTED','B2C','LISTED_TADAWUL');
--   -> 1
--
-- Dry-run: see what would be seeded for a banking tenant (persona 1):
--   SELECT * FROM fn_provision_tenant('t_demo_bank', 1);
--   -> 25 rows (one per framework) showing module + counts of controls/evidence/risks
--
-- Actual seed:
--   CALL sp_seed_tenant('t_demo_bank', 1);
--
-- For an insurance tenant (persona 35):
--   CALL sp_seed_tenant('t_demo_insurer', 35);

-- ============================================================
-- SECTION 15 — CLOSING THE LOOP (feedback arcs + state machines)
-- ============================================================
-- Section 14 only handled DRIVER → SEED (outbound provisioning).
-- The Governance Interdependency doc §2 says the relationship is CIRCULAR:
--
--   driver change → persona re-resolve → framework diff → controls add/remove
--   evidence collected → reviewed → accepted/rejected → risk score updates
--   risk threshold crossed → lifecycle gate BLOCKS go-live/change/audit
--   audit finding → remediation action → new evidence → re-evaluates risk
--   evidence expires → refresh required → if not refreshed → risk rises
--   framework version published → re-bind controls per version_diffs
--   regulator merger/dissolution → re-map regulator_code on all rows
--
-- This section provides the 7 closing arcs as functions/procedures.
-- ============================================================

-- ════════════════════════════════════════════════════════════════════
-- ARC 1 — DRIVER-CHANGE LOOP (re-provision diff)
-- When a tenant changes sector/size/type/model/ownership, recompute
-- the persona and ADD/REMOVE/KEEP frameworks accordingly.
-- ════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION fn_reprovision_tenant_diff(p_tenant_id TEXT)
RETURNS TABLE (
    framework_code TEXT,
    action         TEXT,         -- 'ADD' | 'REMOVE' | 'KEEP' | 'UPGRADE'
    reason         TEXT,
    old_persona    INT,
    new_persona    INT
) LANGUAGE plpgsql AS $$
DECLARE
    v_old_persona INT;
    v_new_persona INT;
    v_old_set     TEXT[];
    v_new_set     TEXT[];
BEGIN
    SELECT persona_id INTO v_old_persona
    FROM tenant.frameworks_subscribed
    WHERE tenant_id = p_tenant_id LIMIT 1;

    SELECT fn_resolve_persona(t.sector, t.size, t.org_type, t.business_model, t.ownership)
      INTO v_new_persona
    FROM tenant.profile t WHERE t.tenant_id = p_tenant_id;

    IF v_old_persona = v_new_persona THEN
        RETURN QUERY SELECT NULL::TEXT, 'NO_CHANGE'::TEXT,
                            'persona unchanged'::TEXT, v_old_persona, v_new_persona;
        RETURN;
    END IF;

    SELECT regexp_split_to_array(mandatory_frameworks||';'||conditional_frameworks, ';\s*')
      INTO v_old_set FROM public.matrix5_composite_personas WHERE persona_id = v_old_persona;
    SELECT regexp_split_to_array(mandatory_frameworks||';'||conditional_frameworks, ';\s*')
      INTO v_new_set FROM public.matrix5_composite_personas WHERE persona_id = v_new_persona;

    RETURN QUERY
    SELECT fc, 'ADD'::TEXT,    'in new persona, not old'::TEXT, v_old_persona, v_new_persona
    FROM unnest(v_new_set) fc WHERE fc <> ALL(v_old_set)
    UNION ALL
    SELECT fc, 'REMOVE'::TEXT, 'in old persona, not new'::TEXT, v_old_persona, v_new_persona
    FROM unnest(v_old_set) fc WHERE fc <> ALL(v_new_set)
    UNION ALL
    SELECT fc, 'KEEP'::TEXT,   'in both personas'::TEXT, v_old_persona, v_new_persona
    FROM unnest(v_new_set) fc WHERE fc = ANY(v_old_set);
END;
$$;

-- Apply the diff: removes obsolete frameworks (preserves evidence for audit trail),
-- adds new ones via sp_seed_tenant slice.
CREATE OR REPLACE PROCEDURE sp_apply_driver_change(p_tenant_id TEXT)
LANGUAGE plpgsql AS $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT * FROM fn_reprovision_tenant_diff(p_tenant_id) LOOP
        IF r.action = 'ADD' THEN
            -- seed only this framework's slice (re-uses logic from sp_seed_tenant)
            INSERT INTO tenant.frameworks_subscribed (tenant_id, framework_code, applicability, persona_id, subscribed_at)
            VALUES (p_tenant_id, r.framework_code, 'mandatory', r.new_persona, NOW())
            ON CONFLICT DO NOTHING;
            -- (controls/evidence/risk seed logic same as sp_seed_tenant, omitted for brevity)
        ELSIF r.action = 'REMOVE' THEN
            -- soft-remove: mark as 'no_longer_applicable' but keep history
            UPDATE tenant.frameworks_subscribed
            SET applicability = 'no_longer_applicable',
                terminated_at = NOW()
            WHERE tenant_id = p_tenant_id AND framework_code = r.framework_code;
            UPDATE tenant.controls
            SET status = 'decommissioned'
            WHERE tenant_id = p_tenant_id AND framework_code = r.framework_code;
        END IF;
    END LOOP;
END;
$$;

-- ════════════════════════════════════════════════════════════════════
-- ARC 2 — EVIDENCE STATE MACHINE
-- DEFINE → APPROVE → IMPLEMENT → MAINTAIN → REVIEW → (ACCEPTED|REJECTED|EXPIRED)
-- ════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION fn_advance_evidence_state(
    p_tenant_id    TEXT,
    p_state_id     INT,
    p_action       TEXT,         -- 'submit' | 'approve' | 'reject' | 'expire' | 'refresh'
    p_actor        TEXT,
    p_actor_role   TEXT
) RETURNS TEXT LANGUAGE plpgsql AS $$
DECLARE
    v_current  TEXT;
    v_next     TEXT;
BEGIN
    SELECT stage_code INTO v_current
    FROM tenant.evidence_lifecycle_state
    WHERE tenant_id = p_tenant_id AND lifecycle_id = p_state_id;

    v_next := CASE
        WHEN v_current='DEFINE'    AND p_action='submit'   THEN 'APPROVE'
        WHEN v_current='APPROVE'   AND p_action='approve'  THEN 'IMPLEMENT'
        WHEN v_current='APPROVE'   AND p_action='reject'   THEN 'DEFINE'
        WHEN v_current='IMPLEMENT' AND p_action='submit'   THEN 'MAINTAIN'
        WHEN v_current='MAINTAIN'  AND p_action='submit'   THEN 'REVIEW'
        WHEN v_current='REVIEW'    AND p_action='approve'  THEN 'ACCEPTED'
        WHEN v_current='REVIEW'    AND p_action='reject'   THEN 'IMPLEMENT'
        WHEN v_current='ACCEPTED'  AND p_action='expire'   THEN 'EXPIRED'
        WHEN v_current='EXPIRED'   AND p_action='refresh'  THEN 'IMPLEMENT'
        ELSE NULL
    END;

    IF v_next IS NULL THEN
        RAISE EXCEPTION 'Invalid transition: % from state %', p_action, v_current;
    END IF;

    UPDATE tenant.evidence_lifecycle_state
       SET stage_code = v_next, updated_at = NOW(),
           updated_by = p_actor, updated_by_role = p_actor_role,
           is_active_stage = (v_next IN ('IMPLEMENT','MAINTAIN','REVIEW','ACCEPTED'))
     WHERE tenant_id = p_tenant_id AND lifecycle_id = p_state_id;

    -- Feed back into risk: rejected/expired evidence raises residual risk
    IF v_next IN ('EXPIRED','REJECTED') THEN
        PERFORM fn_recompute_residual_risk(p_tenant_id, (
            SELECT control_id FROM tenant.evidence_lifecycle_state
            WHERE lifecycle_id = p_state_id LIMIT 1));
    END IF;

    RETURN v_next;
END;
$$;

-- ════════════════════════════════════════════════════════════════════
-- ARC 3 — RISK FEEDBACK LOOP
-- residual_risk = inherent_risk × (1 - control_effectiveness × evidence_freshness)
-- Re-runs whenever evidence state changes or control effectiveness is measured.
-- ════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION fn_recompute_residual_risk(
    p_tenant_id  TEXT,
    p_control_id INT
) RETURNS NUMERIC LANGUAGE plpgsql AS $$
DECLARE
    v_inherent       INT;
    v_effectiveness  INT;       -- 1..5
    v_fresh_pct      NUMERIC;   -- % of required evidence in ACCEPTED state
    v_residual       NUMERIC;
BEGIN
    SELECT inherent_risk_score, control_effectiveness
      INTO v_inherent, v_effectiveness
    FROM tenant.risk_register
    WHERE tenant_id = p_tenant_id AND control_id = p_control_id;

    SELECT COALESCE(
        AVG(CASE WHEN stage_code = 'ACCEPTED' THEN 1.0
                 WHEN stage_code IN ('REVIEW','MAINTAIN') THEN 0.7
                 WHEN stage_code IN ('IMPLEMENT','APPROVE') THEN 0.4
                 WHEN stage_code = 'DEFINE' THEN 0.1
                 WHEN stage_code IN ('EXPIRED','REJECTED') THEN 0.0
                 ELSE 0.0 END),
        0.0)
      INTO v_fresh_pct
    FROM tenant.evidence_lifecycle_state
    WHERE tenant_id = p_tenant_id AND control_id = p_control_id;

    v_residual := v_inherent * (1 - (v_effectiveness::NUMERIC / 5.0) * v_fresh_pct);

    UPDATE tenant.risk_register
       SET residual_risk_score = v_residual,
           residual_risk_level = CASE
               WHEN v_residual >= 16 THEN 'critical'
               WHEN v_residual >= 12 THEN 'high'
               WHEN v_residual >=  6 THEN 'medium'
               ELSE 'low'
           END,
           last_recomputed_at  = NOW()
     WHERE tenant_id = p_tenant_id AND control_id = p_control_id;

    -- Cascade: high residual risk creates a finding
    IF v_residual >= 12 THEN
        INSERT INTO tenant.findings (tenant_id, control_id, severity, source, opened_at)
        VALUES (p_tenant_id, p_control_id,
                CASE WHEN v_residual >= 16 THEN 'critical' ELSE 'high' END,
                'risk_engine', NOW())
        ON CONFLICT (tenant_id, control_id) WHERE status='open' DO NOTHING;
    END IF;

    RETURN v_residual;
END;
$$;

-- ════════════════════════════════════════════════════════════════════
-- ARC 4 — LIFECYCLE GATES (block go-live / change / audit on risk+evidence)
-- ════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION fn_check_lifecycle_gate(
    p_tenant_id TEXT,
    p_gate_type TEXT       -- 'go_live' | 'change_request' | 'audit_submission' | 'cloud_migration'
) RETURNS TABLE (
    decision     TEXT,     -- 'PASS' | 'BLOCK' | 'WARN'
    reason_code  TEXT,
    detail       TEXT
) LANGUAGE plpgsql AS $$
DECLARE
    v_critical_open  INT;
    v_high_open      INT;
    v_evidence_gaps  INT;
    v_unfresh_count  INT;
BEGIN
    SELECT COUNT(*) INTO v_critical_open FROM tenant.risk_register
    WHERE tenant_id = p_tenant_id AND residual_risk_level = 'critical';

    SELECT COUNT(*) INTO v_high_open FROM tenant.risk_register
    WHERE tenant_id = p_tenant_id AND residual_risk_level = 'high';

    SELECT COUNT(*) INTO v_evidence_gaps FROM tenant.evidence_required er
    LEFT JOIN tenant.evidence_lifecycle_state els
      ON els.tenant_id = er.tenant_id AND els.mapping_id = er.mapping_id
    WHERE er.tenant_id = p_tenant_id
      AND er.is_mandatory = true
      AND (els.stage_code IS NULL OR els.stage_code IN ('DEFINE','EXPIRED','REJECTED'));

    SELECT COUNT(*) INTO v_unfresh_count FROM tenant.evidence_lifecycle_state els
    JOIN tenant.evidence_required er
      ON er.mapping_id = els.mapping_id AND er.tenant_id = els.tenant_id
    WHERE els.tenant_id = p_tenant_id
      AND els.stage_code = 'ACCEPTED'
      AND els.updated_at < NOW() - (er.review_frequency_months || ' months')::INTERVAL;

    -- Gate rules (per Governance doc §9 — System lifecycle governance)
    IF p_gate_type = 'go_live' THEN
        IF v_critical_open > 0 THEN
            RETURN QUERY SELECT 'BLOCK','CRITICAL_RISK_OPEN',
                FORMAT('%s critical residual risks must be treated before go-live', v_critical_open);
        ELSIF v_evidence_gaps > 0 THEN
            RETURN QUERY SELECT 'BLOCK','EVIDENCE_GAP',
                FORMAT('%s mandatory evidence items not in ACCEPTED state', v_evidence_gaps);
        ELSIF v_high_open > 0 THEN
            RETURN QUERY SELECT 'WARN','HIGH_RISK_OPEN',
                FORMAT('%s high residual risks; require risk acceptance sign-off', v_high_open);
        ELSE
            RETURN QUERY SELECT 'PASS','ALL_GATES_GREEN','ready for go-live';
        END IF;
    ELSIF p_gate_type = 'change_request' THEN
        IF v_critical_open > 0 THEN
            RETURN QUERY SELECT 'BLOCK','CRITICAL_RISK_OPEN','no changes during critical risk window';
        ELSE
            RETURN QUERY SELECT 'PASS','OK','change permitted';
        END IF;
    ELSIF p_gate_type = 'audit_submission' THEN
        IF v_evidence_gaps > 0 THEN
            RETURN QUERY SELECT 'BLOCK','EVIDENCE_GAP',
                FORMAT('%s evidence gaps + %s stale items', v_evidence_gaps, v_unfresh_count);
        ELSE
            RETURN QUERY SELECT 'PASS','OK','audit pack complete';
        END IF;
    ELSIF p_gate_type = 'cloud_migration' THEN
        -- requires NCA-CCC controls in IMPLEMENT or above
        IF EXISTS (SELECT 1 FROM tenant.controls
                   WHERE tenant_id = p_tenant_id AND framework_code = 'NCA-CCC'
                     AND status NOT IN ('effective','degraded')) THEN
            RETURN QUERY SELECT 'BLOCK','CCC_CONTROLS_NOT_EFFECTIVE',
                'NCA-CCC controls must be effective before cloud migration';
        ELSE
            RETURN QUERY SELECT 'PASS','OK','cloud migration permitted';
        END IF;
    END IF;
END;
$$;

-- ════════════════════════════════════════════════════════════════════
-- ARC 5 — AUDIT FINDING → REMEDIATION → CLOSURE
-- ════════════════════════════════════════════════════════════════════
CREATE OR REPLACE PROCEDURE sp_record_audit_finding(
    p_tenant_id   TEXT,
    p_control_id  INT,
    p_severity    TEXT,
    p_description TEXT,
    p_due_in_days INT DEFAULT 30
) LANGUAGE plpgsql AS $$
DECLARE
    v_finding_id INT;
    v_owner      TEXT;
BEGIN
    SELECT risk_owner_role INTO v_owner FROM tenant.risk_register
    WHERE tenant_id = p_tenant_id AND control_id = p_control_id;

    INSERT INTO tenant.findings (tenant_id, control_id, severity, description, source, opened_at, due_at, status)
    VALUES (p_tenant_id, p_control_id, p_severity, p_description, 'audit', NOW(),
            NOW() + (p_due_in_days || ' days')::INTERVAL, 'open')
    RETURNING finding_id INTO v_finding_id;

    -- Spawn remediation action assigned to the risk owner
    INSERT INTO tenant.remediation_actions
        (tenant_id, finding_id, control_id, assigned_role, due_at, status)
    VALUES (p_tenant_id, v_finding_id, p_control_id, v_owner,
            NOW() + (p_due_in_days || ' days')::INTERVAL, 'pending');

    -- Mark linked evidence as needing refresh
    UPDATE tenant.evidence_lifecycle_state
       SET stage_code = 'IMPLEMENT', is_active_stage = TRUE
     WHERE tenant_id = p_tenant_id AND control_id = p_control_id
       AND stage_code = 'ACCEPTED';

    -- Force risk recomputation
    PERFORM fn_recompute_residual_risk(p_tenant_id, p_control_id);
END;
$$;

CREATE OR REPLACE PROCEDURE sp_close_remediation(
    p_tenant_id      TEXT,
    p_remediation_id INT,
    p_evidence_ref   TEXT
) LANGUAGE plpgsql AS $$
DECLARE
    v_control_id INT;
BEGIN
    UPDATE tenant.remediation_actions
       SET status = 'closed', closed_at = NOW(), closing_evidence = p_evidence_ref
     WHERE tenant_id = p_tenant_id AND remediation_id = p_remediation_id
    RETURNING control_id INTO v_control_id;

    UPDATE tenant.findings
       SET status = 'closed', closed_at = NOW()
     WHERE tenant_id = p_tenant_id
       AND finding_id = (SELECT finding_id FROM tenant.remediation_actions
                         WHERE tenant_id=p_tenant_id AND remediation_id=p_remediation_id);

    -- Re-run risk: now that finding is closed, residual should drop
    PERFORM fn_recompute_residual_risk(p_tenant_id, v_control_id);
END;
$$;

-- ════════════════════════════════════════════════════════════════════
-- ARC 6 — FRAMEWORK VERSION UPGRADE (uses framework_version_diffs)
-- ════════════════════════════════════════════════════════════════════
CREATE OR REPLACE PROCEDURE sp_upgrade_framework_version(
    p_tenant_id     TEXT,
    p_framework     TEXT,
    p_from_version  TEXT,
    p_to_version    TEXT
) LANGUAGE plpgsql AS $$
DECLARE
    r RECORD;
BEGIN
    -- Apply each diff row
    FOR r IN SELECT * FROM public.framework_version_diffs
             WHERE framework_code = p_framework
               AND from_version = p_from_version
               AND to_version = p_to_version LOOP
        IF r.change_type = 'controls_added' THEN
            INSERT INTO tenant.controls (tenant_id, framework_code, framework_version, control_number, status)
            SELECT p_tenant_id, r.framework_code, p_to_version, c.control_number, 'planned'
            FROM public.controls c
            WHERE c.framework_code = r.framework_code
              AND c.framework_version = p_to_version
              AND NOT EXISTS (SELECT 1 FROM tenant.controls tc
                              WHERE tc.tenant_id = p_tenant_id AND tc.control_number = c.control_number);
        ELSIF r.change_type = 'controls_removed' THEN
            UPDATE tenant.controls SET status = 'superseded'
            WHERE tenant_id = p_tenant_id AND framework_code = r.framework_code
              AND framework_version = p_from_version;
        ELSIF r.change_type = 'controls_modified' THEN
            UPDATE tenant.controls SET status = 'review_required'
            WHERE tenant_id = p_tenant_id AND framework_code = r.framework_code;
        END IF;
    END LOOP;

    -- Mark new version active
    UPDATE tenant.frameworks_subscribed
       SET active_version = p_to_version, last_upgraded_at = NOW()
     WHERE tenant_id = p_tenant_id AND framework_code = p_framework;
END;
$$;

-- ════════════════════════════════════════════════════════════════════
-- ARC 7 — CONTINUOUS MONITORING (cron-style cycle drivers)
-- These should be wired to pg_cron or your runner so the cycle keeps turning.
-- ════════════════════════════════════════════════════════════════════

-- 7a. Expire evidence past its max_age_days (daily)
CREATE OR REPLACE PROCEDURE sp_cycle_expire_stale_evidence()
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE tenant.evidence_lifecycle_state els
       SET stage_code = 'EXPIRED', is_active_stage = FALSE, updated_at = NOW()
      FROM tenant.evidence_required er
     WHERE els.mapping_id = er.mapping_id
       AND els.tenant_id  = er.tenant_id
       AND els.stage_code = 'ACCEPTED'
       AND els.updated_at < NOW() - (er.review_frequency_months || ' months')::INTERVAL;
    -- Cascade: re-run risk for affected controls
    PERFORM fn_recompute_residual_risk(tenant_id, control_id)
    FROM tenant.evidence_lifecycle_state
    WHERE stage_code = 'EXPIRED' AND updated_at > NOW() - INTERVAL '5 minutes';
END;
$$;

-- 7b. Trigger audits per matrix4 ownership cadence (daily)
CREATE OR REPLACE PROCEDURE sp_cycle_schedule_audits()
LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO tenant.audit_runs (tenant_id, framework_code, scheduled_at, status)
    SELECT a.tenant_id, a.framework_code, NOW(), 'scheduled'
    FROM tenant.audit_schedule a
    LEFT JOIN tenant.audit_runs r
      ON r.tenant_id = a.tenant_id AND r.framework_code = a.framework_code
    WHERE r.scheduled_at IS NULL
       OR r.scheduled_at < NOW() - CASE a.audit_frequency
             WHEN 'continuous' THEN INTERVAL '1 day'
             WHEN 'quarterly'  THEN INTERVAL '3 months'
             WHEN 'annual'     THEN INTERVAL '12 months'
             ELSE INTERVAL '12 months'
         END;
END;
$$;

-- 7c. Watch for org profile changes and trigger re-provisioning (event-driven)
CREATE OR REPLACE FUNCTION trg_tenant_profile_change() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.sector, NEW.size, NEW.org_type, NEW.business_model, NEW.ownership)
       IS DISTINCT FROM
       (OLD.sector, OLD.size, OLD.org_type, OLD.business_model, OLD.ownership) THEN
        CALL sp_apply_driver_change(NEW.tenant_id);
    END IF;
    RETURN NEW;
END;
$$;
-- CREATE TRIGGER tr_tenant_profile_change AFTER UPDATE ON tenant.profile
--   FOR EACH ROW EXECUTE FUNCTION trg_tenant_profile_change();

-- ════════════════════════════════════════════════════════════════════
-- THE CLOSED CYCLE (per tenant)
-- ════════════════════════════════════════════════════════════════════
--
--                           ┌─────── matrix5/persona ──────┐
--      driver change ───►   │ ARC 1: re-provision diff     │
--                           └────────────┬─────────────────┘
--                                        ▼
--                                  framework set
--                                        │
--                                        ▼
--                             controls + evidence reqs
--                                        │
--           ┌────────────────────────────┼─────────────────────────────┐
--           ▼                            ▼                             ▼
--     ARC 2: evidence            ARC 3: risk score              ARC 6: framework
--     state machine              recompute                       version upgrade
--     (DEFINE→…→ACCEPTED)        (residual = inherent ×          (uses version_diffs;
--           │                     control_effectiveness ×         add/remove/modify
--           │                     evidence_freshness)             tenant.controls)
--           │                            │                             │
--           ▼                            ▼                             ▼
--     ARC 7a: expire              if residual ≥ high                 controls: planned
--     stale evidence              ─► auto-create finding              → effective
--     (cron daily)                │
--           │                     ▼                            ┌─── ARC 4: lifecycle
--           │              ARC 5: audit finding ─►             │    gates
--           │              remediation action                  │    (go_live, change,
--           ▼                     │                            │     audit_submission,
--     evidence refreshed ◄────────┴── close on evidence ──────►│     cloud_migration)
--                                                              │
--                          ARC 7b: scheduled audits ◄──────────┤
--                          (matrix4 ownership cadence)         │
--                                                              ▼
--                                                       PASS / BLOCK / WARN
--
-- Every arc feeds the next; expiry/finding/upgrade all loop back into evidence
-- and risk, which re-evaluate gates. The cycle never stops turning.

-- ================================================================================
-- SECTION 16 — COMPREHENSIVE GRC DATA FLOW ARCHITECTURE
-- ================================================================================
-- End-to-end organizational data lifecycle: ingress → validation → enrichment →
-- engine → storage → activation → governance → archival, with all 7 feedback arcs
-- from §15 wired in. Every byte traverses 8 tiers under continuous DAuth + audit.
-- ================================================================================
--
-- ┌──────────────────────────────────────────────────────────────────────────────────────┐
-- │                                                                                      │
-- │   TIER 1 — INGRESS / DATA CAPTURE                                                    │
-- │   ─────────────────────────────────                                                  │
-- │                                                                                      │
-- │   ┌──────────┐  ┌──────────┐  ┌──────────┐  ┌──────────┐  ┌──────────┐              │
-- │   │ HUMAN    │  │ SYSTEM   │  │ INTEGRA- │  │ DOCUMENT │  │ EXTERNAL │              │
-- │   │ INPUT    │  │ EVENTS   │  │ TIONS    │  │ UPLOAD   │  │ FEEDS    │              │
-- │   │ ─────    │  │ ──────   │  │ ──────   │  │ ──────   │  │ ──────   │              │
-- │   │ • Onbd   │  │ • Login  │  │ • HRIS   │  │ • PDF/   │  │ • Reg-   │              │
-- │   │   wizard │  │ • Tx     │  │ • ITSM   │  │   DOCX   │  │   ulator │              │
-- │   │ • Forms  │  │ • API    │  │ • CMDB   │  │ • Imag-  │  │   feeds  │              │
-- │   │ • Atte-  │  │ • Job    │  │ • ERP    │  │   es     │  │ • Threat │              │
-- │   │   stat'n │  │ • Inci-  │  │ • SIEM   │  │ • Logs   │  │   intel  │              │
-- │   │ • Survey │  │   dent   │  │ • IAM    │  │ • CSV    │  │ • CVE    │              │
-- │   │ • Risk   │  │ • Tele-  │  │ • Cloud  │  │ • XML    │  │ • Frame- │              │
-- │   │   accept │  │   metry  │  │   CSP    │  │   evid   │  │   work   │              │
-- │   │ • DPIA   │  │ • Scan   │  │ • Backup │  │ • Sign'd │  │   ver-   │              │
-- │   │   submit │  │   result │  │ • IDV    │  │   PDFs   │  │   sions  │              │
-- │   └────┬─────┘  └────┬─────┘  └────┬─────┘  └────┬─────┘  └────┬─────┘              │
-- │        │             │             │             │             │                    │
-- │        └─────────────┴─────────────┴─────────────┴─────────────┘                    │
-- │                                    │                                                 │
-- │                    ALL INGRESS PASSES THROUGH GATEWAY                                │
-- │                    (rate-limit · WAF · CSRF · mTLS · DAuth bearer · tenant header)   │
-- │                                    │                                                 │
-- └────────────────────────────────────┼─────────────────────────────────────────────────┘
--                                      ▼
-- ┌──────────────────────────────────────────────────────────────────────────────────────┐
-- │   TIER 2 — VALIDATION & CLASSIFICATION  (every event)                                │
-- │   ────────────────────────────────────────                                           │
-- │                                                                                      │
-- │   ┌─────────────────┐ ┌──────────────────┐ ┌─────────────────────────┐              │
-- │   │ SCHEMA          │ │ TENANT ISOLATION │ │ DATA CLASSIFICATION     │              │
-- │   │ VALIDATION      │ │ ────────────────  │ │ ─────────────────────   │              │
-- │   │ ────────────    │ │ • RLS policy      │ │ NDMO class:             │              │
-- │   │ • Zod / JSON    │ │   tenant_id=$tt   │ │   public                │              │
-- │   │   schema        │ │ • search_path     │ │   internal              │              │
-- │   │ • PK/FK check   │ │ • app.current_    │ │   confidential          │              │
-- │   │ • bounds check  │ │   tenant_id GUC   │ │   restricted            │              │
-- │   │ • PII detector  │ │ • cross-tenant    │ │ Tag → encryption-       │              │
-- │   │ • content hash  │ │   reject          │ │   strength + ret. min   │              │
-- │   └────────┬────────┘ └────────┬──────────┘ └────────────┬────────────┘              │
-- │            │                   │                         │                            │
-- │            └───────────────────┼─────────────────────────┘                            │
-- │                                ▼                                                       │
-- │                   ┌─────────────────────────────┐                                      │
-- │                   │ AUDIT-TRAIL ENTRY           │  (immutable; SHA256 chain)           │
-- │                   │  dos.audit_trail            │                                      │
-- │                   │  actor_id, tenant_id,       │                                      │
-- │                   │  action, before, after,     │                                      │
-- │                   │  ts, prev_hash, this_hash   │                                      │
-- │                   └──────────────┬──────────────┘                                      │
-- │                                  │                                                     │
-- │       reject if invalid ◄────────┼──────► proceed if valid                             │
-- └──────────────────────────────────┼─────────────────────────────────────────────────────┘
--                                    ▼
-- ┌──────────────────────────────────────────────────────────────────────────────────────┐
-- │   TIER 3 — ENRICHMENT & ROUTING                                                       │
-- │   ──────────────────────────────                                                      │
-- │                                                                                      │
-- │   ┌────────────────────────────┐  ┌──────────────────────────┐                       │
-- │   │ CONTEXT ENRICHMENT         │  │ MODULE ROUTING            │                       │
-- │   │ ──────────────────         │  │ ──────────────            │                       │
-- │   │ Lookup against §11:        │  │ from §14 routing CASE:    │                       │
-- │   │ • dim_sectors              │  │ NCA-* → compliance-cyber  │                       │
-- │   │ • dim_org_types            │  │ SAMA-* → compl-financial  │                       │
-- │   │ • dim_org_sizes            │  │ PDPL → privacy            │                       │
-- │   │ • dim_business_models      │  │ CMA-* → governance        │                       │
-- │   │ • dim_ownership            │  │ ZATCA-* → finance-tax     │                       │
-- │   │ → resolve persona_id       │  │ MHRSD-* → team-hr         │                       │
-- │   │                            │  │ MOCI-* → foundation/cust  │                       │
-- │   │ Lookup ownership/RACI:     │  │ PCI/SWIFT → payments      │                       │
-- │   │ • foundation_cat_owner-    │  │ ISO-* → isms              │                       │
