-- ── DDL: missing infrastructure tables for Tiers 5+7+8 ──
-- Tier 5: Evidence vault metadata (blob lives in object store)
CREATE TABLE IF NOT EXISTS dos.evidence_vault (
    vault_id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id         TEXT NOT NULL,
    mapping_id        INT NOT NULL,
    blob_uri          TEXT NOT NULL,           -- s3://bucket/path or minio://
    sha256            TEXT NOT NULL,           -- integrity
    encryption_kms_id TEXT NOT NULL,           -- KMS key reference
    classification    TEXT NOT NULL,           -- public|internal|confidential|restricted
    retention_until   TIMESTAMPTZ NOT NULL,
    legal_hold        BOOLEAN NOT NULL DEFAULT FALSE,
    uploaded_by       TEXT NOT NULL,
    uploaded_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_verified_at  TIMESTAMPTZ
);

-- Tier 7: Per-read access log (every read of evidence/control/risk emits a row)
CREATE TABLE IF NOT EXISTS dos.access_log (
    log_id            BIGSERIAL PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    actor_id          TEXT NOT NULL,
    actor_role        TEXT NOT NULL,
    resource_type     TEXT NOT NULL,           -- 'evidence'|'control'|'risk'|'finding'|'report'
    resource_id       TEXT NOT NULL,
    action            TEXT NOT NULL,           -- 'read'|'export'|'download'
    purpose           TEXT,                    -- declared business purpose (for PDPL)
    ip_addr           INET,
    user_agent        TEXT,
    accessed_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    decision          TEXT NOT NULL,           -- 'allow'|'deny'
    decision_reason   TEXT
);
CREATE INDEX IF NOT EXISTS ix_access_log_tenant_time ON dos.access_log(tenant_id, accessed_at DESC);
CREATE INDEX IF NOT EXISTS ix_access_log_actor_time  ON dos.access_log(actor_id, accessed_at DESC);

-- Tier 7: KRI/KCI continuous monitoring buffer
CREATE TABLE IF NOT EXISTS dos.kri_observations (
    observation_id    BIGSERIAL PRIMARY KEY,
    tenant_id         TEXT NOT NULL,
    kri_code          TEXT NOT NULL,
    framework_code    TEXT,
    value_numeric     NUMERIC,
    threshold_amber   NUMERIC,
    threshold_red     NUMERIC,
    status            TEXT NOT NULL,           -- 'green'|'amber'|'red'
    observed_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    source            TEXT                     -- which scanner/job emitted it
);

-- Tier 8: Disposal certificates (audit-trail of deletions)
CREATE TABLE IF NOT EXISTS dos.disposal_certificate (
    cert_id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id         TEXT NOT NULL,
    vault_id          UUID NOT NULL REFERENCES dos.evidence_vault(vault_id),
    method            TEXT NOT NULL,           -- 'crypto_erase'|'overwrite'|'physical'
    disposed_by       TEXT NOT NULL,           -- system or actor
    disposed_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    legal_basis       TEXT NOT NULL,           -- 'retention_expired'|'pdpl_request'|'gdpr_erasure'
    audit_trail_hash  TEXT NOT NULL            -- linked to dos.audit_trail row
);

-- Tier 8: Archive index (cold tier metadata; blob lives in glacier-equivalent)
CREATE TABLE IF NOT EXISTS dos.archive_index (
    archive_id        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id         TEXT NOT NULL,
    source_table      TEXT NOT NULL,
    source_pk         TEXT NOT NULL,
    archived_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    blob_uri          TEXT NOT NULL,
    sha256            TEXT NOT NULL,
    retention_until   TIMESTAMPTZ NOT NULL,
    restore_sla_hours INT NOT NULL DEFAULT 24
);

-- ============================================================
-- SECTION 17 — TENANT-SIDE DDL (so §14 + §15 procedures compile)
-- ============================================================
-- The functions in §14 (provisioning) and §15 (closing the loop)
-- reference 11 tables under the 'tenant' schema. This section
-- materializes them with proper RLS, FKs, and indexes.
-- ============================================================

-- Per-tenant schema is created during tenant provisioning. The DDL below
-- assumes a 'tenant' schema is the search-path target; a real deployment
-- creates one schema per tenant and templates these tables into it.

CREATE SCHEMA IF NOT EXISTS tenant;

-- 1. tenant.profile — the 9-dimension organization profile
CREATE TABLE IF NOT EXISTS tenant.profile (
    tenant_id          TEXT PRIMARY KEY,
    sector             TEXT NOT NULL REFERENCES public.dim_sectors(code),
    size               TEXT NOT NULL REFERENCES public.dim_org_sizes(code),
    org_type           TEXT NOT NULL REFERENCES public.dim_org_types(code),
    business_model     TEXT NOT NULL REFERENCES public.dim_business_models(code),
    ownership          TEXT NOT NULL REFERENCES public.dim_ownership(code),
    data_classes       TEXT[],            -- public/internal/confidential/restricted/personal/sensitive/health/financial/cardholder/national
    technology_models  TEXT[],            -- cloud/on-prem/hybrid/OT/AI/mobile/api/data-lake/cross-border
    lifecycle_stage    TEXT,              -- design/build/onboarding/production/change/incident/audit/retirement
    jurisdictions      TEXT[],            -- KSA/GCC/EU/US/multi
    licenses           TEXT[],            -- regulator licenses held
    persona_id         INT,               -- resolved by fn_resolve_persona
    created_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 2. tenant.frameworks_subscribed
CREATE TABLE IF NOT EXISTS tenant.frameworks_subscribed (
    tenant_id          TEXT NOT NULL,
    framework_code     TEXT NOT NULL,
    applicability      TEXT NOT NULL,     -- mandatory/conditional/voluntary/no_longer_applicable
    persona_id         INT,
    active_version     TEXT,
    subscribed_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_upgraded_at   TIMESTAMPTZ,
    terminated_at      TIMESTAMPTZ,
    PRIMARY KEY (tenant_id, framework_code)
);

-- 3. tenant.controls
CREATE TABLE IF NOT EXISTS tenant.controls (
    tenant_id          TEXT NOT NULL,
    control_id         INT NOT NULL,
    framework_code     TEXT NOT NULL,
    framework_version  TEXT,
    control_number     TEXT NOT NULL,
    title_en           TEXT,
    title_ar           TEXT,
    requirement_en     TEXT,
    requirement_ar     TEXT,
    control_type       TEXT,
    priority           TEXT,
    maturity_level     INT,
    module_code        TEXT NOT NULL,
    status             TEXT NOT NULL DEFAULT 'planned', -- planned/in-design/in-implementation/effective/degraded/expired/superseded/decommissioned/review_required
    owner_role         TEXT,
    last_reviewed_at   TIMESTAMPTZ,
    PRIMARY KEY (tenant_id, control_id)
);
CREATE INDEX IF NOT EXISTS ix_tenant_controls_fw ON tenant.controls(tenant_id, framework_code);
CREATE INDEX IF NOT EXISTS ix_tenant_controls_module ON tenant.controls(tenant_id, module_code);

-- 4. tenant.evidence_required
CREATE TABLE IF NOT EXISTS tenant.evidence_required (
    tenant_id              TEXT NOT NULL,
    mapping_id             INT NOT NULL,
    control_id             INT NOT NULL,
    framework_code         TEXT NOT NULL,
    evidence_type_code     TEXT NOT NULL,
    is_mandatory           BOOLEAN NOT NULL DEFAULT TRUE,
    retention_months       INT,
    review_frequency_months INT,
    approval_role          TEXT,
    module_code            TEXT NOT NULL,
    status                 TEXT NOT NULL DEFAULT 'requested',
    PRIMARY KEY (tenant_id, mapping_id)
);

-- 5. tenant.evidence_lifecycle_state — the state machine cursor
CREATE TABLE IF NOT EXISTS tenant.evidence_lifecycle_state (
    tenant_id              TEXT NOT NULL,
    lifecycle_id           INT NOT NULL,
    mapping_id             INT NOT NULL,
    control_id             INT NOT NULL,
    framework_code         TEXT NOT NULL,
    stage_code             TEXT NOT NULL,    -- DEFINE/APPROVE/IMPLEMENT/MAINTAIN/REVIEW/ACCEPTED/EXPIRED/REJECTED
    stage_order            INT,
    duration_days          INT,
    responsible_role       TEXT,
    module_code            TEXT,
    is_active_stage        BOOLEAN DEFAULT FALSE,
    vault_id               UUID,             -- → dos.evidence_vault when uploaded
    updated_at             TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_by             TEXT,
    updated_by_role        TEXT,
    PRIMARY KEY (tenant_id, lifecycle_id)
);
CREATE INDEX IF NOT EXISTS ix_tenant_els_active ON tenant.evidence_lifecycle_state(tenant_id, is_active_stage) WHERE is_active_stage;

-- 6. tenant.risk_register
CREATE TABLE IF NOT EXISTS tenant.risk_register (
    tenant_id              TEXT NOT NULL,
    risk_id                INT NOT NULL,
    control_id             INT NOT NULL,
    framework_code         TEXT NOT NULL,
    primary_risk_category  TEXT,
    inherent_risk_score    NUMERIC,
    inherent_risk_level    TEXT,
    control_effectiveness  INT,              -- 1..5
    residual_risk_score    NUMERIC,
    residual_risk_level    TEXT,             -- low/medium/high/critical
    risk_treatment         TEXT,             -- accept/mitigate/transfer/avoid
    risk_owner_role        TEXT,
    module_code            TEXT,
    last_recomputed_at     TIMESTAMPTZ,
    PRIMARY KEY (tenant_id, risk_id),
    UNIQUE (tenant_id, control_id)
);

-- 7. tenant.findings
CREATE TABLE IF NOT EXISTS tenant.findings (
    finding_id     SERIAL,
    tenant_id      TEXT NOT NULL,
    control_id     INT NOT NULL,
    severity       TEXT NOT NULL,           -- low/medium/high/critical
    description    TEXT,
    source         TEXT,                    -- 'audit'|'risk_engine'|'kri'|'self_assessment'|'regulator'
    opened_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    due_at         TIMESTAMPTZ,
    closed_at      TIMESTAMPTZ,
    status         TEXT NOT NULL DEFAULT 'open',
    PRIMARY KEY (tenant_id, finding_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_findings_open
    ON tenant.findings(tenant_id, control_id) WHERE status = 'open';

-- 8. tenant.remediation_actions
CREATE TABLE IF NOT EXISTS tenant.remediation_actions (
