-- 9. tenant.audit_schedule (driven by matrix4 ownership cadence)
CREATE TABLE IF NOT EXISTS tenant.audit_schedule (
    tenant_id        TEXT NOT NULL,
    framework_code   TEXT NOT NULL,
    scrutiny_level   TEXT,
    audit_frequency  TEXT,                   -- continuous/quarterly/annual
