-- ── RLS policies (defence in depth alongside search_path isolation) ──
ALTER TABLE tenant.profile                   ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant.frameworks_subscribed     ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant.controls                  ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant.evidence_required         ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant.evidence_lifecycle_state  ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant.risk_register             ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant.findings                  ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant.remediation_actions       ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant.audit_schedule            ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant.audit_runs                ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant.persona_evidence_pack     ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE
    t TEXT;
BEGIN
    FOR t IN SELECT unnest(ARRAY[
        'profile','frameworks_subscribed','controls','evidence_required',
        'evidence_lifecycle_state','risk_register','findings',
        'remediation_actions','audit_schedule','audit_runs','persona_evidence_pack'
    ]) LOOP
        EXECUTE FORMAT(
            'CREATE POLICY p_isolate_%1$s ON tenant.%1$s FOR ALL ' ||
            'USING (tenant_id = current_setting(''app.current_tenant_id'', true))',
            t
        );
    END LOOP;
END$$;

-- ============================================================
-- SECTION 18 — CANONICAL 12-LAYER REFERENCE + 4 GAP-CLOSURES
-- ============================================================
-- The user's canonical 12-layer Mermaid architecture is now
-- the authoritative reference — see DATA_FLOW_ARCHITECTURE.md
-- This section materializes the 4 gaps that diagram exposed.
-- ============================================================

-- KEY DESIGN RULE (operational invariant):
--   The data lifecycle never depends on 'page exists' or 'table exists'
--   as proof of readiness. A capability is usable only when this chain
--   is green:
--     TenantProvisioningPlan → module readiness → schema/RLS → RBAC →
--     OpenFGA scope → seed/bootstrap data → Dynamic UI enrollment →
--     API hydration → audit trail → monitoring evidence
-- ============================================================

-- ════════════════════════════════════════════════════════════════════
-- GAP CLOSURE 1 — DECLARATIVE TenantProvisioningPlan (Layer 4)
-- Replaces script-driven provisioning. Plan is the single source of
-- truth for what a tenant gets.
-- ════════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS dos.tenant_provisioning_plan (
    plan_id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id          TEXT NOT NULL,
    product_code       TEXT NOT NULL,           -- 'shahin'|'admin'|'consultant'
    edition_code       TEXT NOT NULL,           -- 'starter'|'pro'|'enterprise'|'platinum'
    persona_id         INT NOT NULL REFERENCES public.matrix5_composite_personas(persona_id),
    modules            TEXT[] NOT NULL,         -- ['foundation','compliance-cyber','privacy',...]
    role_grants        JSONB NOT NULL,          -- {role_code: [user_id, ...]}
    readiness_gates    JSONB NOT NULL,          -- {gate_name: {required: bool, deadline: timestamptz}}
    plan_version       INT NOT NULL DEFAULT 1,
    status             TEXT NOT NULL DEFAULT 'draft',  -- draft/active/superseded/cancelled
    created_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    activated_at       TIMESTAMPTZ,
    superseded_by      UUID
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_tpp_active
    ON dos.tenant_provisioning_plan(tenant_id) WHERE status = 'active';

-- ════════════════════════════════════════════════════════════════════
-- GAP CLOSURE 2 — MODULE READINESS CONTRACT (Layer 4)
-- A capability is not exposed in UI until its contract is green.
-- One row per (tenant, module) tracks all readiness signals.
-- ════════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS dos.module_readiness_contract (
    tenant_id              TEXT NOT NULL,
    module_code            TEXT NOT NULL,
    -- the 9 readiness signals from the operational invariant
    plan_active            BOOLEAN NOT NULL DEFAULT FALSE,
    schema_migrated        BOOLEAN NOT NULL DEFAULT FALSE,
    rls_attached           BOOLEAN NOT NULL DEFAULT FALSE,
    rbac_seeded            BOOLEAN NOT NULL DEFAULT FALSE,
    fga_scope_provisioned  BOOLEAN NOT NULL DEFAULT FALSE,
    bootstrap_data_loaded  BOOLEAN NOT NULL DEFAULT FALSE,
    dynamic_ui_enrolled    BOOLEAN NOT NULL DEFAULT FALSE,
    api_hydrated           BOOLEAN NOT NULL DEFAULT FALSE,
    audit_emitting         BOOLEAN NOT NULL DEFAULT FALSE,
    monitoring_observed    BOOLEAN NOT NULL DEFAULT FALSE,
    -- aggregate
    overall_status         TEXT GENERATED ALWAYS AS (
        CASE WHEN plan_active AND schema_migrated AND rls_attached AND rbac_seeded
                AND fga_scope_provisioned AND bootstrap_data_loaded
                AND dynamic_ui_enrolled AND api_hydrated AND audit_emitting
                AND monitoring_observed
             THEN 'green'
             WHEN plan_active AND schema_migrated AND rbac_seeded
             THEN 'amber'
             ELSE 'red'
        END
    ) STORED,
    last_checked_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (tenant_id, module_code)
);

-- Capability gate: returns whether a route/widget should be visible
CREATE OR REPLACE FUNCTION fn_capability_available(
    p_tenant_id    TEXT,
    p_module_code  TEXT
) RETURNS BOOLEAN LANGUAGE sql STABLE AS $$
    SELECT COALESCE(
        (SELECT overall_status = 'green'
         FROM dos.module_readiness_contract
         WHERE tenant_id = p_tenant_id AND module_code = p_module_code),
        FALSE);
$$;

-- ════════════════════════════════════════════════════════════════════
-- GAP CLOSURE 3 — OBLIGATION ENGINE (Layer 8)
-- The granular layer between framework and control that regulators
-- actually audit against. PDPL Art-12 → 72h breach notification → N
-- controls; SAMA-CSF 3.1.1 → board attestation → N controls.
-- ════════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS public.obligations (
    obligation_id      SERIAL PRIMARY KEY,
    framework_code     TEXT NOT NULL REFERENCES public.dim_frameworks(code),
    obligation_code    TEXT NOT NULL,           -- 'PDPL-Art-12'|'SAMA-CSF-3.1.1-1'
    title_en           TEXT NOT NULL,
    title_ar           TEXT,
    description_en     TEXT,
    description_ar     TEXT,
    trigger_condition  TEXT,                    -- e.g. 'data breach detected', 'control failure'
    deadline_hours     INT,                     -- e.g. 4 (SAMA), 72 (SDAIA)
    legal_reference    TEXT,                    -- 'Royal Decree M/19 Art-12'
    severity           TEXT NOT NULL,           -- low/medium/high/critical
    UNIQUE (framework_code, obligation_code)
);

-- Many-to-many: one obligation → many controls; one control → many obligations
CREATE TABLE IF NOT EXISTS public.obligation_controls (
    obligation_id      INT NOT NULL REFERENCES public.obligations(obligation_id),
    control_id         INT NOT NULL,
    framework_code     TEXT NOT NULL,
    control_number     TEXT NOT NULL,
    coverage           TEXT NOT NULL,           -- 'primary'|'supporting'|'compensating'
    PRIMARY KEY (obligation_id, control_id, framework_code, control_number)
);

-- The engine: evaluate obligation status for a tenant
CREATE OR REPLACE FUNCTION fn_evaluate_obligation_status(
    p_tenant_id      TEXT,
    p_obligation_id  INT
) RETURNS TABLE (
    status              TEXT,        -- 'satisfied'|'gap'|'overdue'|'no_evidence'
    coverage_pct        NUMERIC,
    primary_controls    INT,
    primary_implemented INT,
    deadline_status     TEXT
) LANGUAGE plpgsql AS $$
BEGIN
    RETURN QUERY
    WITH obligation_controls_status AS (
        SELECT oc.coverage,
               COUNT(*) AS total,
               COUNT(*) FILTER (
                 WHERE EXISTS (
                   SELECT 1 FROM tenant.controls tc
                   WHERE tc.tenant_id = p_tenant_id
                     AND tc.control_id = oc.control_id
                     AND tc.status IN ('effective','degraded')
                 )
               ) AS implemented
        FROM public.obligation_controls oc
        WHERE oc.obligation_id = p_obligation_id
        GROUP BY oc.coverage
    )
    SELECT
        CASE
          WHEN COALESCE((SELECT implemented FROM obligation_controls_status WHERE coverage='primary'),0) = 0
            THEN 'no_evidence'
          WHEN COALESCE((SELECT implemented FROM obligation_controls_status WHERE coverage='primary'),0)
             < COALESCE((SELECT total FROM obligation_controls_status WHERE coverage='primary'),1)
            THEN 'gap'
          ELSE 'satisfied'
        END::TEXT,
        COALESCE((SELECT implemented::NUMERIC / NULLIF(total,0) * 100
                  FROM obligation_controls_status WHERE coverage='primary'),0)::NUMERIC,
        COALESCE((SELECT total FROM obligation_controls_status WHERE coverage='primary'),0)::INT,
        COALESCE((SELECT implemented FROM obligation_controls_status WHERE coverage='primary'),0)::INT,
        'in_window'::TEXT;
END;
$$;

-- ════════════════════════════════════════════════════════════════════
-- GAP CLOSURE 4 — OPT → GOV/CTRL/RISK BACK-FEEDBACK (Layer 11)
-- Automatic policy updates when weak controls are detected.
-- ════════════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS dos.control_optimization_signals (
    signal_id          BIGSERIAL PRIMARY KEY,
    tenant_id          TEXT NOT NULL,
    control_id         INT NOT NULL,
    framework_code     TEXT NOT NULL,
    weak_signal_type   TEXT NOT NULL,           -- 'low_effectiveness'|'frequent_findings'|'evidence_drift'|'high_residual'
    severity           TEXT NOT NULL,
    detected_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    suggested_action   TEXT NOT NULL,           -- 'tighten_policy'|'add_compensating_control'|'increase_test_frequency'|'replace_control'
    recommendation     TEXT,
    actioned_at        TIMESTAMPTZ,
    actioned_by        TEXT
);

-- Detector: scan all tenant controls and emit signals
CREATE OR REPLACE PROCEDURE sp_detect_weak_controls(p_tenant_id TEXT)
LANGUAGE plpgsql AS $$
BEGIN
    -- Signal type 1: low effectiveness (<3 of 5)
    INSERT INTO dos.control_optimization_signals
        (tenant_id, control_id, framework_code, weak_signal_type, severity, suggested_action, recommendation)
    SELECT p_tenant_id, control_id, framework_code, 'low_effectiveness', 'medium',
           'increase_test_frequency',
           FORMAT('Effectiveness %s/5 — increase test frequency from annual to quarterly', control_effectiveness)
    FROM tenant.risk_register
    WHERE tenant_id = p_tenant_id
      AND control_effectiveness < 3
      AND NOT EXISTS (
          SELECT 1 FROM dos.control_optimization_signals s
          WHERE s.tenant_id = p_tenant_id AND s.control_id = tenant.risk_register.control_id
            AND s.weak_signal_type = 'low_effectiveness' AND s.actioned_at IS NULL);

    -- Signal type 2: frequent findings (≥3 in last 90d)
    INSERT INTO dos.control_optimization_signals
        (tenant_id, control_id, framework_code, weak_signal_type, severity, suggested_action, recommendation)
    SELECT p_tenant_id, f.control_id, c.framework_code, 'frequent_findings', 'high',
           'add_compensating_control',
           FORMAT('%s findings in last 90 days — add compensating control', COUNT(*))
    FROM tenant.findings f
    JOIN tenant.controls c ON c.control_id = f.control_id AND c.tenant_id = f.tenant_id
    WHERE f.tenant_id = p_tenant_id
      AND f.opened_at > NOW() - INTERVAL '90 days'
    GROUP BY f.control_id, c.framework_code
    HAVING COUNT(*) >= 3
    ON CONFLICT DO NOTHING;

    -- Signal type 3: high residual risk (≥ 12)
    INSERT INTO dos.control_optimization_signals
        (tenant_id, control_id, framework_code, weak_signal_type, severity, suggested_action, recommendation)
    SELECT p_tenant_id, control_id, framework_code, 'high_residual', 'high',
           'tighten_policy',
           FORMAT('Residual %.1f — tighten policy or replace control', residual_risk_score)
    FROM tenant.risk_register
    WHERE tenant_id = p_tenant_id AND residual_risk_score >= 12
    ON CONFLICT DO NOTHING;
END;
$$;

-- Action handler: apply a signal's suggested action
CREATE OR REPLACE PROCEDURE sp_action_optimization_signal(
    p_signal_id  BIGINT,
    p_actor      TEXT
) LANGUAGE plpgsql AS $$
DECLARE
    v_action     TEXT;
    v_control_id INT;
    v_tenant_id  TEXT;
BEGIN
    SELECT suggested_action, control_id, tenant_id
      INTO v_action, v_control_id, v_tenant_id
    FROM dos.control_optimization_signals
    WHERE signal_id = p_signal_id;

    CASE v_action
        WHEN 'increase_test_frequency' THEN
            -- Update audit_schedule for this control's framework
            UPDATE tenant.audit_schedule
               SET audit_frequency = 'quarterly'
             WHERE tenant_id = v_tenant_id
               AND framework_code = (SELECT framework_code FROM tenant.controls
                                     WHERE tenant_id=v_tenant_id AND control_id=v_control_id);
        WHEN 'add_compensating_control' THEN
            -- Spawn a finding to track addition of compensating control
            INSERT INTO tenant.findings (tenant_id, control_id, severity, description, source, opened_at, status)
            VALUES (v_tenant_id, v_control_id, 'high',
                    'OPT engine: add compensating control',
                    'optimization_engine', NOW(), 'open');
        WHEN 'tighten_policy' THEN
            -- Mark control for policy review
            UPDATE tenant.controls
               SET status = 'review_required'
             WHERE tenant_id = v_tenant_id AND control_id = v_control_id;
        WHEN 'replace_control' THEN
            -- Deeper action: defer to Arc 6 framework upgrade flow
            UPDATE tenant.controls
               SET status = 'review_required'
             WHERE tenant_id = v_tenant_id AND control_id = v_control_id;
    END CASE;

    UPDATE dos.control_optimization_signals
       SET actioned_at = NOW(), actioned_by = p_actor
     WHERE signal_id = p_signal_id;
END;
$$;

-- ════════════════════════════════════════════════════════════════════
-- THE FULL CYCLE NOW CLOSED (per the canonical 12-layer model)
-- ════════════════════════════════════════════════════════════════════
--
-- Layer 1-2  capture → routes through Layer 3 IAM → Layer 5 validation
--                                                              │
--                                                              ▼
-- Layer 4  TenantProvisioningPlan (declarative) ─► Module Readiness Contract
--          (capability not exposed until contract = 'green')   │
--                                                              ▼
-- Layer 6  canonical stores (foundation, governance, risk, controls,
--          evidence vault, immutable audit trail)              │
--                                                              ▼
-- Layer 7  control points emit audit ◄──────── Layer 8 framework→
--                                              obligation→control→evidence
--                                                              │
-- Layer 9  risk register fed by Layer 8 gaps                   │
--                                                              ▼
-- Layer 10 events → metrics → alerts → AI ──► triggers Layer 7 workflow
--                                                              │
-- Layer 11 dashboards/reports/audit packs ──► OPT detects weak controls
--          ──► back-feeds Layer 6 GOV/CTRL/RISK                │
--          ──► back-feeds Layer 4 TenantProvisioningPlan       │
--                                                              ▼
-- Layer 12 retention → archive → legal hold → controlled purge
--          ──► purge writes to audit trail (deletion ledger)   │
--                                                              ▼
-- Layer 6  AUDIT TRAIL ──► Layer 10 monitoring (closes loop)
--
-- Every byte that enters Layer 1 traverses 3→5→6 and emits at every
-- control point in 7. Compliance evaluation in 8 produces gap signals
-- to 9, which feed alerts in 10, which trigger workflows in 7. Layer 11
-- continuously back-feeds Layers 4, 6, and 11. Layer 12 retains under
-- regulator-driven policy and writes disposal certificates back into
-- Layer 6 audit trail. The cycle never stops.

-- ================================================================================
-- SECTION 19 — AUTONOMY SPINE DDL (the map made concrete)
-- ================================================================================
-- Materializes AUTONOMOUS_OPERATING_MAP.md:
--   Part 1 spine     → event_log, agent_registry, action_library, decision_log, agent_memory
--   Part 2 ownership → agent_layer_ownership, agent_arc_ownership
--   Part 3 events    → event_subscriptions
--   Part 4 loops     → loop_definitions, loop_runs
--   Part 5 registries → module/route/widget/action/capability/rule/kpi
--   Part 6 ladder    → agent_autonomy_levels, autonomy_promotion_log
-- ================================================================================

-- ════════════════════════════════════════════════════════════════════
-- PART 1 — THE SPINE (5 primitives)
-- ════════════════════════════════════════════════════════════════════

-- 1.1 Event bus (append-only, replayable)
CREATE TABLE IF NOT EXISTS dos.event_log (
    event_id        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    event_type      TEXT NOT NULL,                  -- 'event.evidence.expired' etc
    event_family    TEXT GENERATED ALWAYS AS (split_part(event_type,'.',2)) STORED,
    tenant_id       TEXT,
    actor_id        TEXT,                           -- emitting actor (system|agent_id|user_id)
    correlation_id  UUID,                           -- chains related events
    causation_id    UUID,                           -- the event that caused this one
    payload         JSONB NOT NULL,
    emitted_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    -- replay support
    replay_seq      BIGSERIAL,
    -- integrity (ledger-grade)
    prev_hash       TEXT,
    this_hash       TEXT
);
CREATE INDEX IF NOT EXISTS ix_event_log_type_time   ON dos.event_log(event_type, emitted_at DESC);
CREATE INDEX IF NOT EXISTS ix_event_log_tenant_time ON dos.event_log(tenant_id, emitted_at DESC);
CREATE INDEX IF NOT EXISTS ix_event_log_correlation ON dos.event_log(correlation_id);

-- 1.2 Agent registry (the 13 employees)
CREATE TABLE IF NOT EXISTS dos.agent_registry (
    agent_id            TEXT PRIMARY KEY,           -- 'A01'..'A13'
    role_label_en       TEXT NOT NULL,
    role_label_ar       TEXT,
    description_en      TEXT,
    schedule_type       TEXT NOT NULL,              -- 'event_driven'|'continuous'|'cron'|'on_demand'
    cron_expression     TEXT,                       -- when schedule_type='cron'
    timezone            TEXT NOT NULL DEFAULT 'Asia/Riyadh',
    manager_role        TEXT,                       -- escalation target
    is_active           BOOLEAN NOT NULL DEFAULT TRUE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Seed the 13 canonical agents
INSERT INTO dos.agent_registry (agent_id, role_label_en, schedule_type, cron_expression) VALUES
  ('A01','Onboarding & Provisioning','event_driven',NULL),
  ('A02','Identity & Access','continuous',NULL),
  ('A03','Policy','cron','0 9 * * MON'),
