  ('A05','Evidence','cron','0 2 * * *'),
  ('A06','Control','cron','0 7 * * MON'),
  ('A07','Risk','continuous',NULL),
  ('A08','Audit','event_driven',NULL),
  ('A09','Vendor / Third-Party','cron','0 9 * * MON'),
  ('A10','Assurance / Regulator','cron','0 9 1 */3 *'),
  ('A11','Incident','continuous',NULL),
  ('A12','Governance / Executive','cron','0 9 * * MON'),
  ('A13','Sales Development','continuous',NULL)
ON CONFLICT (agent_id) DO NOTHING;

-- 1.3 Action library (atomic operations agents can perform)
CREATE TABLE IF NOT EXISTS dos.action_library (
    action_code         TEXT PRIMARY KEY,
    action_name         TEXT NOT NULL,
    description         TEXT,
    inputs_schema       JSONB NOT NULL,             -- JSON schema of accepted inputs
    side_effects        TEXT[] NOT NULL,            -- ['write:tenant.controls', 'emit:event.x']
    idempotency_key_fn  TEXT,                       -- SQL fn to compute key (prevents double-fire)
    required_perms      TEXT[],                     -- DAuth perms needed
    autonomy_min_level  INT NOT NULL DEFAULT 2,     -- L0..L5; below = HITL required
    is_reversible       BOOLEAN NOT NULL DEFAULT FALSE,
    rollback_action     TEXT                        -- action to call on rollback
);

-- 1.4 Action log (every agent action — audit-grade)
CREATE TABLE IF NOT EXISTS dos.action_log (
    action_log_id       BIGSERIAL PRIMARY KEY,
    agent_id            TEXT NOT NULL REFERENCES dos.agent_registry(agent_id),
    action_code         TEXT NOT NULL REFERENCES dos.action_library(action_code),
    tenant_id           TEXT,
    triggered_by_event  UUID REFERENCES dos.event_log(event_id),
    inputs              JSONB,
    outputs             JSONB,
    decision_id         BIGINT,                     -- → decision_log
    autonomy_level      INT NOT NULL,
    started_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at        TIMESTAMPTZ,
    status              TEXT NOT NULL DEFAULT 'running', -- running|succeeded|failed|rolled_back
    error_message       TEXT,
    idempotency_key     TEXT,
    audit_signature     TEXT                        -- HMAC over the action; verifiable
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_action_log_idempo
    ON dos.action_log(action_code, idempotency_key) WHERE idempotency_key IS NOT NULL;

-- 1.5 Decision engine log (rules-first, LLM-assisted, policy-bounded)
CREATE TABLE IF NOT EXISTS dos.decision_log (
    decision_id         BIGSERIAL PRIMARY KEY,
    agent_id            TEXT NOT NULL REFERENCES dos.agent_registry(agent_id),
    triggered_by_event  UUID REFERENCES dos.event_log(event_id),
    decision_path       TEXT NOT NULL,              -- 'rule:R0042'|'llm:reasoning'|'policy:block'
    rule_code           TEXT,
    llm_model           TEXT,
    llm_prompt_hash     TEXT,                       -- for reproducibility
    llm_tokens_in       INT,
    llm_tokens_out      INT,
    chosen_action       TEXT REFERENCES dos.action_library(action_code),
    confidence          NUMERIC,                    -- 0..1
    policy_check        TEXT NOT NULL,              -- 'allowed'|'denied'|'requires_hitl'
    hitl_assignee_role  TEXT,                       -- when requires_hitl
    decided_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    rationale           TEXT
);

-- 1.6 Agent memory (per-agent learning + context)
CREATE TABLE IF NOT EXISTS dos.agent_memory (
    memory_id           BIGSERIAL PRIMARY KEY,
    agent_id            TEXT NOT NULL REFERENCES dos.agent_registry(agent_id),
    tenant_id           TEXT,
    memory_type         TEXT NOT NULL,              -- 'preference'|'pattern'|'failure'|'success'|'context'
    scope               TEXT NOT NULL,              -- 'tenant'|'global'|'persona'
    key                 TEXT NOT NULL,
    value               JSONB NOT NULL,
    confidence          NUMERIC,
    learned_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_used_at        TIMESTAMPTZ,
    use_count           INT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS ix_agent_memory_lookup
    ON dos.agent_memory(agent_id, scope, key);

