-- ════════════════════════════════════════════════════════════════════
-- PART 7 — THE ORCHESTRATOR (the function that ties everything)
-- ════════════════════════════════════════════════════════════════════
-- Called whenever an event lands. Routes to all listening agents,
-- runs decision engine, executes action, logs everything.
CREATE OR REPLACE FUNCTION fn_emit_event(
    p_event_type      TEXT,
    p_tenant_id       TEXT,
    p_payload         JSONB,
    p_actor_id        TEXT DEFAULT 'system',
    p_correlation_id  UUID DEFAULT NULL,
    p_causation_id    UUID DEFAULT NULL
) RETURNS UUID LANGUAGE plpgsql AS $$
DECLARE
    v_event_id UUID;
    v_prev_hash TEXT;
    v_this_hash TEXT;
    s RECORD;
BEGIN
    -- compute hash chain
    SELECT this_hash INTO v_prev_hash
    FROM dos.event_log ORDER BY replay_seq DESC LIMIT 1;

    v_this_hash := encode(sha256(
        COALESCE(v_prev_hash,'')||p_event_type||COALESCE(p_tenant_id,'')||p_payload::TEXT||NOW()::TEXT
    )::bytea, 'hex');

    INSERT INTO dos.event_log (event_type, tenant_id, actor_id, correlation_id, causation_id,
                               payload, prev_hash, this_hash)
    VALUES (p_event_type, p_tenant_id, p_actor_id, p_correlation_id, p_causation_id,
            p_payload, v_prev_hash, v_this_hash)
    RETURNING event_id INTO v_event_id;

    -- Route to subscribers (exact + wildcard match)
    FOR s IN
        SELECT * FROM dos.event_subscriptions
        WHERE is_active = TRUE
          AND (event_type = p_event_type
               OR p_event_type LIKE replace(event_type,'*','%'))
    LOOP
        -- enqueue handler invocation
        -- (in production: pg_notify or outbox pattern; here we INSERT a placeholder)
        INSERT INTO dos.action_log (agent_id, action_code, tenant_id, triggered_by_event,
                                    inputs, autonomy_level, status)
        VALUES (s.listening_agent, s.handler_action, p_tenant_id, v_event_id,
                p_payload, 2, 'queued')
        ON CONFLICT (action_code, idempotency_key) DO NOTHING;
    END LOOP;

    RETURN v_event_id;
END;
$$;

-- ════════════════════════════════════════════════════════════════════
-- HEALTH CHECK — verify the spine is wired
-- ════════════════════════════════════════════════════════════════════
CREATE OR REPLACE VIEW dos.v_autonomy_health AS
SELECT
  (SELECT COUNT(*) FROM dos.agent_registry WHERE is_active)        AS active_agents,
  (SELECT COUNT(*) FROM dos.loop_definitions)                      AS loops_defined,
  (SELECT COUNT(*) FROM dos.event_subscriptions WHERE is_active)   AS event_subscriptions,
  (SELECT COUNT(*) FROM dos.action_library)                        AS actions_in_library,
  (SELECT COUNT(*) FROM dos.module_readiness_contract
                                 WHERE overall_status='green')     AS modules_green,
  (SELECT COUNT(*) FROM dos.event_log
                                 WHERE emitted_at > NOW()-INTERVAL '24h') AS events_last_24h,
  (SELECT COUNT(*) FROM dos.action_log
                                 WHERE status='succeeded' AND completed_at > NOW()-INTERVAL '24h') AS actions_succeeded_24h,
  (SELECT COUNT(*) FROM dos.loop_runs
                                 WHERE status='running' AND triggered_at < NOW()-INTERVAL '72h') AS stuck_loops;

-- Expected steady state: stuck_loops = 0, events flowing, actions succeeding > 95%.

