-- ════════════════════════════════════════════════════════════════════
-- 20.10 — PATCHED fn_emit_event (writes to dos.system_events, not dos.event_log)
-- ════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION fn_emit_event(
    p_event_type      TEXT,
    p_tenant_id       TEXT,
    p_payload         JSONB,
    p_actor_id        TEXT DEFAULT 'system',
    p_correlation_id  UUID DEFAULT NULL,
    p_causation_id    UUID DEFAULT NULL
) RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE
    v_event_id  BIGINT;
    v_prev_hash TEXT;
    v_this_hash TEXT;
    s RECORD;
BEGIN
    SELECT this_hash INTO v_prev_hash
    FROM dos.system_events ORDER BY id DESC LIMIT 1;

    v_this_hash := encode(sha256(
        (COALESCE(v_prev_hash,'')||p_event_type||COALESCE(p_tenant_id,'')||p_payload::TEXT||NOW()::TEXT)::bytea
    ), 'hex');

    INSERT INTO dos.system_events (event_type, source, payload,
                                    tenant_id, actor_id, correlation_id, causation_id,
                                    event_family, prev_hash, this_hash, occurred_at)
    VALUES (p_event_type, 'autonomy_engine', p_payload,
            p_tenant_id, p_actor_id, p_correlation_id, p_causation_id,
            split_part(p_event_type,'.',2), v_prev_hash, v_this_hash, NOW())
    RETURNING id INTO v_event_id;

    -- Route to listening agents (exact + wildcard match)
    FOR s IN
        SELECT * FROM dos.event_subscriptions
        WHERE is_active = TRUE
          AND (event_type = p_event_type
               OR p_event_type LIKE replace(event_type,'*','%'))
    LOOP
        INSERT INTO dos.action_log (agent_id, action_code, tenant_id, triggered_by_event,
                                    inputs, autonomy_level, status)
        VALUES (s.listening_agent, s.handler_action, p_tenant_id, NULL,  -- triggered_by_event UUID col disabled here; use event_id BIGINT in extended schema
                p_payload, 2, 'queued')
        ON CONFLICT (action_code, idempotency_key) DO NOTHING;
    END LOOP;

    RETURN v_event_id;
END;
$$;

