-- 20.13 — VERIFICATION VIEW (run after applying §20)
-- ════════════════════════════════════════════════════════════════════
CREATE OR REPLACE VIEW dos.v_reconciliation_status AS
SELECT
  'controls extended'                      AS check_name,
  EXISTS(SELECT 1 FROM information_schema.columns
          WHERE table_schema='dos' AND table_name='controls'
            AND column_name='requirement_en') AS passed
UNION ALL SELECT 'system_events extended',
  EXISTS(SELECT 1 FROM information_schema.columns
          WHERE table_schema='dos' AND table_name='system_events'
            AND column_name='correlation_id')
UNION ALL SELECT 'module_registry extended',
  EXISTS(SELECT 1 FROM information_schema.columns
          WHERE table_schema='dos' AND table_name='module_registry'
            AND column_name='owner_agent')
UNION ALL SELECT '6 new SoD rules',
  (SELECT COUNT(*) FROM dos.foundation_sod_rules
    WHERE rule_code IN ('risk_treatment_self_approval','finding_opener_vs_remediator',
                         'deployer_vs_readiness_signoff','incident_reporter_vs_investigator',
                         'audit_executor_vs_signer','profile_editor_vs_persona_approver')) = 6
UNION ALL SELECT 'agent registry mapping populated',
  (SELECT COUNT(*) FROM dos.agent_registry WHERE dyn_ui_agent_ids IS NOT NULL) >= 13
UNION ALL SELECT '3 new dynamic_ui_agents',
  (SELECT COUNT(*) FROM dos.dynamic_ui_agents
    WHERE agent_id IN ('vendor-companion','incident-companion','sdr-companion')) = 3;

-- Run: SELECT * FROM dos.v_reconciliation_status;
-- Expected: every row passed=true.
